previewCss:
.darma-loader-piston-engine {
  display: flex;
  gap: 6px;
  align-items: flex-end;
  width: 52px;
  height: 44px;
}
.darma-loader-piston-engine i {
  position: relative;
  width: 12px;
  height: 40px;
  border: 2px solid #c7d2fe;
  border-radius: 3px;
  box-sizing: border-box;
  overflow: hidden;
}
.darma-loader-piston-engine i::before {
  content: "";
  position: absolute;
  left: 1px;
  right: 1px;
  bottom: 0;
  height: 14px;
  border-radius: 2px;
  background: var(--loader-color, #6366f1);
  animation: darma-loader-piston-engine-pump 0.8s ease-in-out infinite;
}
.darma-loader-piston-engine i:nth-child(1)::before { animation-delay: 0s; }
.darma-loader-piston-engine i:nth-child(2)::before { animation-delay: 0.16s; }
.darma-loader-piston-engine i:nth-child(3)::before { animation-delay: 0.32s; }
@keyframes darma-loader-piston-engine-pump {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-20px); }
}

